import { createTestApp } from './setup/test-app';
import {
  closeTestDataSource,
  resetDatabaseSchema,
  truncateBusinessTables,
} from './setup/test-database';

jest.setTimeout(30000);

describe('Company API (e2e)', () => {
  let app: INestApplication;
  let dataSource: DataSource;
  let companySeq = 0;

  beforeAll(async () => {
    await resetDatabaseSchema();
    app = await createTestApp();
    dataSource = app.get(DataSource);
    await truncateBusinessTables(dataSource);
  });

  afterAll(async () => {
    if (app) {
      await app.close();
    }

    await closeTestDataSource();
  });

  it('creates a valid company and fetches it', async () => {
    // Verifies a company can be created and fetched by id.
    const payload = buildCompanyPayload('create', {
      status: CompanyStatus.ACTIVE,
      industry: Industry.TECHNOLOGY,
    });

    const createResponse = await request(app.getHttpServer())
      .post('/api/companies')
      .send(payload)
      .expect(201);

    expect(createResponse.body).toMatchObject({
      success: true,
      message: 'Company created successfully',
    });

    const detailResponse = await request(app.getHttpServer())
      .get(`/api/companies/${createResponse.body.companyId}`)
      .expect(200);

    expect(detailResponse.body).toMatchObject({
      id: createResponse.body.companyId,
      name: payload.name,
      email: payload.email,
      phone: payload.phone,
      website: payload.website,
      status: payload.status,
      industry: payload.industry,
    });
  });

  it('uses the default status when status is omitted', async () => {
    // Verifies the API applies the default company status.
    const payload = buildCompanyPayload('default-status');
    delete payload.status;

    const createResponse = await request(app.getHttpServer())
      .post('/api/companies')
      .send(payload)
      .expect(201);

    const detailResponse = await request(app.getHttpServer())
      .get(`/api/companies/${createResponse.body.companyId}`)
      .expect(200);

    expect(detailResponse.body.status).toBe(CompanyStatus.PENDING);
  });

  it('rejects missing required fields', async () => {
    // Verifies validation rejects requests missing required fields.
    const response = await request(app.getHttpServer())
      .post('/api/companies')
      .send({
        email: 'company-required@test.local',
      })
      .expect(400);

    expect(response.body).toMatchObject({
      success: false,
      statusCode: 400,
      code: 'VALIDATION_ERROR',
    });
    expect(response.body.details.errors).toEqual(
      expect.arrayContaining([expect.objectContaining({ field: 'name' })]),
    );
  });

  it('rejects invalid company fields and unknown properties', async () => {
    // Verifies validation rejects invalid fields and extra payload properties.
    const response = await request(app.getHttpServer())
      .post('/api/companies')
      .send({
        name: 'codex-e2e-invalid-company',
        email: 'invalid-email',
        website: 'not-a-url',
        status: 'BAD_STATUS',
        industry: 'BAD_INDUSTRY',
        extraField: 'blocked',
      })
      .expect(400);

    expect(response.body).toMatchObject({
      success: false,
      statusCode: 400,
      code: 'VALIDATION_ERROR',
    });
    expect(response.body.details.errors).toEqual(
      expect.arrayContaining([
        expect.objectContaining({ field: 'email' }),
        expect.objectContaining({ field: 'website' }),
        expect.objectContaining({ field: 'status' }),
        expect.objectContaining({ field: 'industry' }),
        expect.objectContaining({ field: 'extraField' }),
      ]),
    );
  });

  it('supports default pagination, filters, and out-of-range pages', async () => {
    // Verifies list pagination, filtering, and empty last-page behavior.
    const activeTechA = await createCompany('list-a', {
      status: CompanyStatus.ACTIVE,
      industry: Industry.TECHNOLOGY,
      phone: '555-101',
    });
    await createCompany('list-b', {
      status: CompanyStatus.ACTIVE,
      industry: Industry.TECHNOLOGY,
      phone: '555-102',
    });
    await createCompany('list-c', {
      status: CompanyStatus.INACTIVE,
      industry: Industry.FINANCE,
      phone: '555-103',
    });

    const defaultList = await request(app.getHttpServer())
      .get('/api/companies')
      .expect(200);

    expect(defaultList.body.page).toBe(1);
    expect(defaultList.body.pageSize).toBe(10);

    const filteredList = await request(app.getHttpServer())
      .get(
        `/api/companies?q=555-10&status=${CompanyStatus.ACTIVE}&industry=${Industry.TECHNOLOGY}&page=1&pageSize=1`,
      )
      .expect(200);

    expect(filteredList.body.total).toBe(2);
    expect(filteredList.body.page).toBe(1);
    expect(filteredList.body.pageSize).toBe(1);
    expect(filteredList.body.totalPages).toBe(2);
    expect(filteredList.body.items).toHaveLength(1);

    const lastPage = await request(app.getHttpServer())
      .get(
        `/api/companies?q=555-10&status=${CompanyStatus.ACTIVE}&industry=${Industry.TECHNOLOGY}&page=3&pageSize=1`,
      )
      .expect(200);

    expect(lastPage.body.items).toEqual([]);

    const detail = await request(app.getHttpServer())
      .get(`/api/companies/${activeTechA}`)
      .expect(200);

    expect(detail.body.phone).toBe('555-101');
  });

  it('distinguishes invalid uuid from missing company', async () => {
    // Verifies invalid ids and missing entities return different errors.
    const invalidResponse = await request(app.getHttpServer())
      .get('/api/companies/not-a-uuid')
      .expect(400);

    expect(invalidResponse.body).toMatchObject({
      success: false,
      statusCode: 400,
      code: 'INVALID_UUID',
    });

    const missingResponse = await request(app.getHttpServer())
      .get('/api/companies/7f4f54f7-cd3c-4ef2-b22d-8f1d68d9f1aa')
      .expect(404);

    expect(missingResponse.body).toMatchObject({
      success: false,
      statusCode: 404,
      code: 'ENTITY_NOT_FOUND',
    });
  });

  it('updates a company', async () => {
    // Verifies partial company updates persist successfully.
    const companyId = await createCompany('update');

    const response = await request(app.getHttpServer())
      .post(`/api/companies/${companyId}`)
      .send({
        name: 'codex-e2e-company-updated',
        status: CompanyStatus.INACTIVE,
        industry: Industry.RETAIL,
      })
      .expect(201);

    expect(response.body).toMatchObject({
      id: companyId,
      name: 'codex-e2e-company-updated',
      status: CompanyStatus.INACTIVE,
      industry: Industry.RETAIL,
    });
  });

  it('deletes a company without contacts and blocks delete with contacts', async () => {
    // Verifies delete succeeds without contacts and fails with blocking contacts.
    const removableCompanyId = await createCompany('delete-free');
    const blockedCompanyId = await createCompany('delete-blocked');

    await dataSource.query(
      `
        INSERT INTO "contacts" ("id", "companyId", "name", "email", "phone", "role", "createdAt", "updatedAt")
        VALUES (gen_random_uuid(), $1, 'Delete Blocker', 'delete-blocker@test.local', '0200-9000', 'User', NOW(), NOW())
      `,
      [blockedCompanyId],
    );

    await request(app.getHttpServer())
      .delete(`/api/companies/${removableCompanyId}`)
      .expect(204);

    const deletedDetail = await request(app.getHttpServer())
      .get(`/api/companies/${removableCompanyId}`)
      .expect(404);

    expect(deletedDetail.body.code).toBe('ENTITY_NOT_FOUND');

    const blockedResponse = await request(app.getHttpServer())
      .delete(`/api/companies/${blockedCompanyId}`)
      .expect(409);

    expect(blockedResponse.body).toMatchObject({
      success: false,
      statusCode: 409,
      code: 'REFERENTIAL_INTEGRITY_VIOLATION',
    });
  });

  async function createCompany(
    scope: string,
    overrides: Partial<CompanyPayload> = {},
  ): Promise<string> {
    const payload = buildCompanyPayload(scope, overrides);
    const response = await request(app.getHttpServer())
      .post('/api/companies')
      .send(payload)
      .expect(201);

    return response.body.companyId;
  }

  function buildCompanyPayload(
    scope: string,
    overrides: Partial<CompanyPayload> = {},
  ): CompanyPayload {
    companySeq += 1;

    return {
      name: `codex-e2e-company-${scope}-${companySeq}`,
      email: `company-${companySeq}@test.local`,
      phone: `0100-${String(companySeq).padStart(4, '0')}`,
      website: `https://company-${companySeq}.example.com`,
      status: CompanyStatus.PENDING,
      industry: Industry.OTHER,
      ...overrides,
    };
  }
});

type CompanyPayload = {
  name: string;
  email: string;
  phone: string;
  website: string;
  status?: CompanyStatus;
  industry: Industry;
};

import { INestApplication } from '@nestjs/common';
import { DataSource } from 'typeorm';
import request from 'supertest';
import { createTestApp } from './setup/test-app';
import {
  closeTestDataSource,
  resetDatabaseSchema,
  truncateBusinessTables,
} from './setup/test-database';

jest.setTimeout(30000);

describe('Contact API (e2e)', () => {
  let app: INestApplication;
  let dataSource: DataSource;
  let companySeq = 0;
  let contactSeq = 0;

  beforeAll(async () => {
    await resetDatabaseSchema();
    app = await createTestApp();
    dataSource = app.get(DataSource);
    await truncateBusinessTables(dataSource);
  });

  afterAll(async () => {
    if (app) {
      await app.close();
    }

    await closeTestDataSource();
  });

  it('creates a contact for an existing company and fetches it', async () => {
    // Verifies a contact can be created under an existing company.
    const companyId = await createCompany('contact-create');
    const payload = buildContactPayload('create', { companyId });

    const createResponse = await request(app.getHttpServer())
      .post('/api/contacts')
      .send(payload)
      .expect(201);

    expect(createResponse.body).toMatchObject({
      companyId,
      name: payload.name,
      email: payload.email,
      phone: payload.phone,
      role: payload.role,
    });

    const detailResponse = await request(app.getHttpServer())
      .get(`/api/contacts/${createResponse.body.id}`)
      .expect(200);

    expect(detailResponse.body).toMatchObject({
      id: createResponse.body.id,
      companyId,
      name: payload.name,
    });
  });

  it('returns PARENT_NOT_FOUND for an unknown companyId', async () => {
    // Verifies contact creation fails when the parent company is missing.
    const response = await request(app.getHttpServer())
      .post('/api/contacts')
      .send(
        buildContactPayload('missing-company', {
          companyId: '7f4f54f7-cd3c-4ef2-b22d-8f1d68d9f1aa',
        }),
      )
      .expect(404);

    expect(response.body).toMatchObject({
      success: false,
      statusCode: 404,
      code: 'PARENT_NOT_FOUND',
    });
  });

  it('rejects invalid fields and unknown properties', async () => {
    // Verifies validation rejects malformed contact payloads.
    const response = await request(app.getHttpServer())
      .post('/api/contacts')
      .send({
        companyId: 'not-a-uuid',
        email: 'invalid-email',
        phone: '0200-0001',
        extraField: 'blocked',
      })
      .expect(400);

    expect(response.body).toMatchObject({
      success: false,
      statusCode: 400,
      code: 'VALIDATION_ERROR',
    });
    expect(response.body.details.errors).toEqual(
      expect.arrayContaining([
        expect.objectContaining({ field: 'companyId' }),
        expect.objectContaining({ field: 'name' }),
        expect.objectContaining({ field: 'email' }),
        expect.objectContaining({ field: 'extraField' }),
      ]),
    );
  });

  it('supports companyId, q, role, pagination, and sorting', async () => {
    // Verifies list filters, pagination, and sort order for contacts.
    const companyId = await createCompany('contact-list');
    const otherCompanyId = await createCompany('contact-list-other');
    await createContact('list-c', {
      companyId,
      name: 'codex-e2e-contact-list-c',
      role: 'User',
    });
    await createContact('list-a', {
      companyId,
      name: 'codex-e2e-contact-list-a',
      role: 'Decision Maker',
    });
    await createContact('list-b', {
      companyId,
      name: 'codex-e2e-contact-list-b',
      role: 'Decision Maker',
    });
    await createContact('list-outside', {
      companyId: otherCompanyId,
      name: 'codex-e2e-contact-list-outside',
      role: 'Decision Maker',
    });

    const response = await request(app.getHttpServer())
      .get(
        `/api/contacts?companyId=${companyId}&q=codex-e2e-contact-list&role=Decision%20Maker&sort=name&order=asc&page=1&pageSize=1`,
      )
      .expect(200);

    expect(response.body.total).toBe(2);
    expect(response.body.page).toBe(1);
    expect(response.body.pageSize).toBe(1);
    expect(response.body.totalPages).toBe(2);
    expect(response.body.items).toHaveLength(1);
    expect(response.body.items[0]).toMatchObject({
      companyId,
      name: 'codex-e2e-contact-list-a',
      role: 'Decision Maker',
    });
  });

  it('distinguishes invalid uuid from missing contact', async () => {
    // Verifies invalid ids and missing contacts return different errors.
    const invalidResponse = await request(app.getHttpServer())
      .get('/api/contacts/not-a-uuid')
      .expect(400);

    expect(invalidResponse.body).toMatchObject({
      success: false,
      statusCode: 400,
      code: 'INVALID_UUID',
    });

    const missingResponse = await request(app.getHttpServer())
      .get('/api/contacts/7f4f54f7-cd3c-4ef2-b22d-8f1d68d9f1ab')
      .expect(404);

    expect(missingResponse.body).toMatchObject({
      success: false,
      statusCode: 404,
      code: 'ENTITY_NOT_FOUND',
    });
  });

  it('updates a contact and moves it to another existing company', async () => {
    // Verifies a contact can be updated and reassigned to another company.
    const sourceCompanyId = await createCompany('move-source');
    const targetCompanyId = await createCompany('move-target');
    const contactId = await createContact('move-contact', {
      companyId: sourceCompanyId,
    });

    const response = await request(app.getHttpServer())
      .post(`/api/contacts/${contactId}`)
      .send({
        companyId: targetCompanyId,
        role: 'Technical Buyer',
        phone: '0200-UPDATED',
      })
      .expect(201);

    expect(response.body).toMatchObject({
      id: contactId,
      companyId: targetCompanyId,
      role: 'Technical Buyer',
      phone: '0200-UPDATED',
    });
  });

  it('keeps the original data when moving to an unknown company', async () => {
    // Verifies failed reassignment does not mutate the original contact.
    const companyId = await createCompany('move-missing-company');
    const contactId = await createContact('move-missing-contact', {
      companyId,
    });

    const response = await request(app.getHttpServer())
      .post(`/api/contacts/${contactId}`)
      .send({
        companyId: '7f4f54f7-cd3c-4ef2-b22d-8f1d68d9f1aa',
      })
      .expect(404);

    expect(response.body).toMatchObject({
      success: false,
      statusCode: 404,
      code: 'PARENT_NOT_FOUND',
    });

    const detailResponse = await request(app.getHttpServer())
      .get(`/api/contacts/${contactId}`)
      .expect(200);

    expect(detailResponse.body.companyId).toBe(companyId);
  });

  it('soft deletes a contact', async () => {
    // Verifies soft-deleted contacts are no longer returned by the API.
    const companyId = await createCompany('contact-delete');
    const contactId = await createContact('delete', { companyId });

    await request(app.getHttpServer())
      .delete(`/api/contacts/${contactId}`)
      .expect(204);

    const detailResponse = await request(app.getHttpServer())
      .get(`/api/contacts/${contactId}`)
      .expect(404);

    expect(detailResponse.body).toMatchObject({
      success: false,
      statusCode: 404,
      code: 'ENTITY_NOT_FOUND',
    });
  });

  async function createCompany(scope: string): Promise<string> {
    companySeq += 1;

    const response = await request(app.getHttpServer())
      .post('/api/companies')
      .send({
        name: `codex-e2e-company-${scope}-${companySeq}`,
        email: `contact-company-${companySeq}@test.local`,
        phone: `0100-${String(companySeq).padStart(4, '0')}`,
        website: `https://contact-company-${companySeq}.example.com`,
      })
      .expect(201);

    return response.body.companyId;
  }

  async function createContact(
    scope: string,
    overrides: Partial<ContactPayload> = {},
  ): Promise<string> {
    const payload = buildContactPayload(scope, overrides);
    const response = await request(app.getHttpServer())
      .post('/api/contacts')
      .send(payload)
      .expect(201);

    return response.body.id;
  }

  function buildContactPayload(
    scope: string,
    overrides: Partial<ContactPayload> = {},
  ): ContactPayload {
    contactSeq += 1;

    return {
      companyId: '00000000-0000-4000-8000-000000000001',
      name: `codex-e2e-contact-${scope}-${contactSeq}`,
      email: `contact-${contactSeq}@test.local`,
      phone: `0200-${String(contactSeq).padStart(4, '0')}`,
      role: 'User',
      ...overrides,
    };
  }
});

type ContactPayload = {
  companyId: string;
  name: string;
  email: string;
  phone: string;
  role: string;
};

import { DataSource } from 'typeorm';
import {
  closeTestDataSource,
  getTestDataSource,
  listConstraintNames,
  listIndexNames,
} from './setup/test-database';

jest.setTimeout(30000);

describe('Database migrations (e2e)', () => {
  let dataSource: DataSource;

  beforeAll(async () => {
    dataSource = await getTestDataSource();
  });

  afterAll(async () => {
    await closeTestDataSource();
  });

  beforeEach(async () => {
    await dataSource.query('DROP SCHEMA IF EXISTS public CASCADE');
    await dataSource.query('CREATE SCHEMA public');
    await dataSource.query('CREATE EXTENSION IF NOT EXISTS "uuid-ossp"');
    await dataSource.query('CREATE EXTENSION IF NOT EXISTS "pgcrypto"');
    await dataSource.synchronize();
  });

  it('runs the migration on a clean schema', async () => {
    // Verifies the migration creates the expected constraint and index.
    await dataSource.runMigrations();

    await expect(listConstraintNames(dataSource, 'contacts')).resolves.toEqual(
      expect.arrayContaining(['fk_contacts_company_id']),
    );
    await expect(listIndexNames(dataSource, 'contacts')).resolves.toEqual(
      expect.arrayContaining(['idx_contacts_company_id']),
    );
  });

  it('rolls back the migration', async () => {
    // Verifies rollback removes the migration artifacts.
    await dataSource.runMigrations();
    await dataSource.undoLastMigration();

    await expect(
      listConstraintNames(dataSource, 'contacts'),
    ).resolves.not.toContain('fk_contacts_company_id');
    await expect(listIndexNames(dataSource, 'contacts')).resolves.not.toContain(
      'idx_contacts_company_id',
    );
  });

  it('can rerun the migration after rollback', async () => {
    // Verifies the migration can be applied again after rollback.
    await dataSource.runMigrations();
    await dataSource.undoLastMigration();
    await dataSource.runMigrations();

    await expect(
      listConstraintNames(dataSource, 'contacts'),
    ).resolves.toContain('fk_contacts_company_id');
  });

  it('prevents orphan companyId values', async () => {
    // Verifies the foreign key blocks orphan contact rows.
    await dataSource.runMigrations();

    await expect(
      dataSource.query(
        `
          INSERT INTO "contacts" ("id", "companyId", "name", "email", "phone", "role", "createdAt", "updatedAt")
          VALUES (gen_random_uuid(), $1, 'Orphan Contact', 'orphan@test.local', '0200-7777', 'User', NOW(), NOW())
        `,
        ['7f4f54f7-cd3c-4ef2-b22d-8f1d68d9f1aa'],
      ),
    ).rejects.toThrow(/fk_contacts_company_id/i);
  });
});

import { MutationCache, QueryCache, QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { enqueueSnackbar, SnackbarProvider } from 'notistack';
import { RouterProvider } from 'react-router-dom';

// project imports
import { isTransportError } from 'api/request';
import { RouteAccessProvider } from 'contexts/RouteAccessContext';
import router from 'routes';
import ThemeCustomization from 'themes';

// Transport-level failures (network errors, 5xx) aren't tied to a specific page/action,
// so they're toasted here once. Business errors (4xx) are left for the calling
// component to interpret and display (see isTransportError in api/request.js).
function handleTransportError(error) {
  if (isTransportError(error)) {
    enqueueSnackbar(error?.message || 'Something went wrong, please try again later.', { variant: 'error' });
  }
}

const queryClient = new QueryClient({
  queryCache: new QueryCache({ onError: handleTransportError }),
  mutationCache: new MutationCache({ onError: handleTransportError }),
});

// ==============================|| APP - THEME, ROUTER, LOCAL ||============================== //

export default function App() {
  return (
    <QueryClientProvider client={queryClient}>
      <ThemeCustomization>
        <SnackbarProvider maxSnack={3} anchorOrigin={{ vertical: 'bottom', horizontal: 'right' }}>
          <RouteAccessProvider>
            <RouterProvider router={router} />
          </RouteAccessProvider>
        </SnackbarProvider>
      </ThemeCustomization>
    </QueryClientProvider>
  );
}
import { createBrowserRouter } from 'react-router-dom';

import MainRoutes from './MainRoutes';

const router = createBrowserRouter([MainRoutes], { basename: import.meta.env.VITE_APP_BASE_NAME });

export default router;
import { createElement, lazy } from 'react';
import { Navigate } from 'react-router-dom';

// project imports
import Loadable from 'components/Loadable';
import Layout from 'layout';
import { protectRoute } from './ProtectedRoute';
import { routeDefinitions } from './route-registry';

const componentsById = Object.fromEntries(routeDefinitions.map((definition) => [definition.id, Loadable(lazy(definition.loader))]));
const defaultRoutes = routeDefinitions.filter((definition) => definition.default);

if (defaultRoutes.length !== 1) {
  throw new Error('Exactly one default route must be configured.');
}

const [defaultRoute] = defaultRoutes;

// ==============================|| MAIN ROUTING ||============================== //

const MainRoutes = {
  path: '/',
  element: <Layout />,
  children: [
    {
      index: true,
      element: <Navigate replace to={`/${defaultRoute.path}`} />
    },
    ...routeDefinitions.map((definition) => ({
      path: definition.path,
      element: protectRoute(definition.accessId ?? definition.id, createElement(componentsById[definition.id]))
    }))
  ]
};

export default MainRoutes;
