import type { PaginatedResult } from '../types/paginated-result.type';

const DEFAULT_PAGE = 1;
const DEFAULT_PAGE_SIZE = 10;
const MAX_PAGE_SIZE = 100;

export type PaginationQueryInput = {
  page?: number | string;
  pageSize?: number | string;
};

export function resolvePagination(query: PaginationQueryInput) {
  const page = normalizePositiveInteger(query.page, DEFAULT_PAGE);
  const pageSize = Math.min(
    normalizePositiveInteger(query.pageSize, DEFAULT_PAGE_SIZE),
    MAX_PAGE_SIZE,
  );

  return {
    page,
    pageSize,
    skip: (page - 1) * pageSize,
    take: pageSize,
  };
}

export function buildPaginatedResult<TItem>(args: {
  items: TItem[];
  page: number;
  pageSize: number;
  total: number;
}): PaginatedResult<TItem> {
  const { items, page, pageSize, total } = args;

  return {
    items,
    page,
    pageSize,
    total,
    totalPages: total === 0 ? 0 : Math.ceil(total / pageSize),
  };
}

function normalizePositiveInteger(
  value: number | string | undefined,
  fallback: number,
) {
  const parsedValue =
    typeof value === 'number' ? value : Number.parseInt(value ?? '', 10);

  if (!Number.isFinite(parsedValue) || parsedValue < 1) {
    return fallback;
  }

  return parsedValue;
}
import {
  buildPaginatedResult,
  resolvePagination,
} from './pagination.util';

describe('pagination.util', () => {
  it('uses default page and pageSize', () => {
    // Verifies the default pagination values.
    expect(resolvePagination({})).toEqual({
      page: 1,
      pageSize: 10,
      skip: 0,
      take: 10,
    });
  });

  it('caps pageSize at 100', () => {
    // Verifies the maximum pageSize limit.
    expect(resolvePagination({ page: 2, pageSize: 999 })).toEqual({
      page: 2,
      pageSize: 100,
      skip: 100,
      take: 100,
    });
  });

  it('falls back for invalid values', () => {
    // Verifies fallback behavior for invalid pagination input.
    expect(resolvePagination({ page: 0, pageSize: 'NaN' })).toEqual({
      page: 1,
      pageSize: 10,
      skip: 0,
      take: 10,
    });
  });

  it('calculates skip and take from valid input', () => {
    // Verifies skip/take calculation for a valid page request.
    expect(resolvePagination({ page: '3', pageSize: '25' })).toEqual({
      page: 3,
      pageSize: 25,
      skip: 50,
      take: 25,
    });
  });

  it('returns zero totalPages for empty results', () => {
    // Verifies pagination metadata for an empty result set.
    expect(
      buildPaginatedResult({
        items: [],
        page: 4,
        pageSize: 10,
        total: 0,
      }),
    ).toEqual({
      items: [],
      page: 4,
      pageSize: 10,
      total: 0,
      totalPages: 0,
    });
  });
});

export type PaginatedResult<TItem> = {
  items: TItem[];
  page: number;
  pageSize: number;
  total: number;
  totalPages: number;
};

import { Repository, FindManyOptions, ObjectLiteral } from 'typeorm';
import {
  resolvePagination,
  buildPaginatedResult,
} from '../../common/utils/pagination.util';

export class BaseRepository<T extends ObjectLiteral> extends Repository<T> {
  /**
   * Execute a paginated query using standardized pagination utilities
   *
   * @param page The current page number (starts from 1)
   * @param limit The number of items per page
   * @param options Additional TypeORM query options
   */
  async paginate(
    page: number | string = 1,
    limit: number | string = 10,
    options?: FindManyOptions<T>,
  ) {
    const {
      page: validPage,
      pageSize: validLimit,
      skip,
      take,
    } = resolvePagination({
      page,
      pageSize: limit,
    });

    const [items, total] = await this.findAndCount({
      ...options,
      skip,
      take,
    });

    return buildPaginatedResult({
      items,
      total,
      page: validPage,
      pageSize: validLimit,
    });
  }
}

