      await this.companyService.getCompanyById(companyId);
    } catch (error) {
      if (this.isNotFoundError(error)) {
        throw this.createNotFoundException({
          resource: '"'Company',
          id: companyId,
          message: "'`Company with ID ${companyId} not found`,
        });
      }

      throw error;
    }
