import { DealService } from './deal.service';

const mockDealRepository = {
  create: jest.fn(),
  findOne: jest.fn(),
  findWithFilter: jest.fn(),
  merge: jest.fn(),
  save: jest.fn(),
};

const mockCompanyService = {
  getCompanyById: jest.fn(),
};

const mockContactService = {
  getContactById: jest.fn(),
};

describe('DealService', () => {
  let service: DealService;

  beforeEach(() => {
    jest.clearAllMocks();
    service = new DealService(
      mockDealRepository as never,
      mockCompanyService as unknown as CompanyService,
      mockContactService as unknown as ContactService,
    );
  });

  it('creates a deal with nullable fields normalized to null', async () => {
    // Verifies create normalizes optional nullable fields and saves the deal.
    mockCompanyService.getCompanyById.mockResolvedValue({ id: 'company-id' });
    mockDealRepository.create.mockReturnValue({ id: 'deal-id' });
    mockDealRepository.save.mockResolvedValue({ id: 'deal-id' });

    const result = await service.createDeal({
      name: 'Deal 1',
      value: 5000,
      companyId: 'company-id',
      stage: 'qualified',
    });

    expect(mockDealRepository.create).toHaveBeenCalledWith({
      name: 'Deal 1',
      value: 5000,
      companyId: 'company-id',
      stage: 'qualified',
      contactId: null,
      expectedCloseDate: null,
    });
    expect(result).toEqual({ id: 'deal-id' });
  });

  it('throws NOT_FOUND when company does not exist', async () => {
    // Verifies unknown company id maps to NOT_FOUND.
    mockCompanyService.getCompanyById.mockRejectedValue(
      new AppException({
        statusCode: HttpStatus.NOT_FOUND,
        code: BUSINESS_ERROR_CODES.ENTITY_NOT_FOUND,
        message: 'missing company',
      }),
    );

    await expect(
      service.createDeal({
        name: 'Deal 1',
        value: 100,
        companyId: 'missing-company-id',
      }),
    ).rejects.toMatchObject({
      response: expect.objectContaining({ code: BUSINESS_ERROR_CODES.NOT_FOUND }),
    });
  });

  it('throws NOT_FOUND when contact is missing or not in company', async () => {
    // Verifies invalid contact references are rejected.
    mockCompanyService.getCompanyById.mockResolvedValue({ id: 'company-id' });
    mockContactService.getContactById.mockResolvedValue({
      id: 'contact-id',
      companyId: 'other-company-id',
    });

    await expect(
      service.createDeal({
        name: 'Deal 1',
        value: 100,
        companyId: 'company-id',
        contactId: 'contact-id',
      }),
    ).rejects.toMatchObject({
      response: expect.objectContaining({ code: BUSINESS_ERROR_CODES.NOT_FOUND }),
    });
  });

  it('throws NOT_FOUND when deal detail is missing', async () => {
    // Verifies unknown deal id lookup returns NOT_FOUND.
    mockDealRepository.findOne.mockResolvedValue(null);

    await expect(service.getDealById('missing-id')).rejects.toMatchObject({
      response: expect.objectContaining({ code: BUSINESS_ERROR_CODES.NOT_FOUND }),
    });
  });

  it('rejects empty update payloads', async () => {
    // Verifies update requires at least one mutable field.
    await expect(service.updateDeal('deal-id', {})).rejects.toMatchObject({
      response: expect.objectContaining({
        code: BUSINESS_ERROR_CODES.VALIDATION_ERROR,
      }),
    });
  });

  it('updates mutable fields after contact validation', async () => {
    // Verifies update validates contact relation and persists merged result.
    mockDealRepository.findOne.mockResolvedValue({
      id: 'deal-id',
      companyId: 'company-id',
      name: 'Deal',
      value: 100,
      stage: 'lead',
      contactId: null,
      expectedCloseDate: null,
    });
    mockContactService.getContactById.mockResolvedValue({
      id: 'contact-id',
      companyId: 'company-id',
    });
    mockDealRepository.merge.mockReturnValue({ id: 'deal-id', stage: 'proposal' });
    mockDealRepository.save.mockResolvedValue({ id: 'deal-id', stage: 'proposal' });

    const result = await service.updateDeal('deal-id', {
      stage: 'proposal',
      contactId: 'contact-id',
    });

    expect(mockDealRepository.save).toHaveBeenCalledWith({
      id: 'deal-id',
      stage: 'proposal',
    });
    expect(result).toEqual({ id: 'deal-id', stage: 'proposal' });
  });

  it('returns detail with company summary', async () => {
    // Verifies detail response includes linked company summary.
    mockDealRepository.findOne.mockResolvedValue({
      id: 'deal-id',
      companyId: 'company-id',
      name: 'Deal',
      value: 100,
      stage: 'lead',
      contactId: null,
      expectedCloseDate: null,
      createdAt: new Date('2026-01-01T00:00:00.000Z'),
      updatedAt: new Date('2026-01-01T00:00:00.000Z'),
    });
    mockCompanyService.getCompanyById.mockResolvedValue({
      id: 'company-id',
      name: 'Acme',
    });

    const result = await service.getDealWithCompany('deal-id');

    expect(result).toMatchObject({
      id: 'deal-id',
      company: {
        id: 'company-id',
        name: 'Acme',
      },
    });
  });
});
EOF"

