import {
  Autocomplete,
  Button,
  CircularProgress,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  MenuItem,
  Stack,
  TextField,
} from '@mui/material';
import { useEffect, useState } from 'react';

import { formatForDatetimeLocal } from 'utils/formatDate';
import { useCompanyList } from '../companies/companyQueries';
import { useContactList } from '../contacts/contactQueries';

const emptyValues = { companyId: '', contactId: null, name: '', stage: 'lead', value: '', expectedCloseDate: '' };
const stageOptions = ['lead', 'qualified', 'proposal', 'negotiation', 'closed-won', 'closed-lost'];

function normalizeCloseDate(value) {
  if (!value) {
    return '';
  }

  if (/^\d{4}-\d{2}-\d{2}$/.test(value)) {
    return value;
  }

  return formatForDatetimeLocal(value).slice(0, 10);
}

export function DealFormDialog({
  initialValues,
  isPending,
  mode,
  onClose,
  onSubmit,
  open,
}) {
  const [values, setValues] = useState(emptyValues);
  const [touched, setTouched] = useState({ companyId: false, name: false, stage: false, value: false });

  const companiesQuery = useCompanyList({ page: 1, pageSize: 100 });
  const contactsQuery = useContactList({
    companyId: values.companyId || undefined,
    page: 1,
    pageSize: 100,
  });

  const companyOptions = companiesQuery.data?.items ?? [];
  const contactOptions = values.companyId ? contactsQuery.data?.items ?? [] : [];

  const selectedCompany = companyOptions.find((company) => company.id === values.companyId) ?? null;
  const selectedContact = contactOptions.find((contact) => contact.id === values.contactId) ?? null;

  const parsedValue = Number(values.value);
  const isValueValid =
    values.value !== '' && Number.isFinite(parsedValue) && parsedValue >= 0;

  const errors = {
    companyId: !values.companyId ? 'Company is required.' : '',
    name: !values.name?.trim()
      ? 'Name is required.'
      : values.name.trim().length > 255
        ? 'Name must be 255 characters or fewer.'
        : '',
    stage: !values.stage?.trim()
      ? 'Stage is required.'
      : values.stage.trim().length > 100
        ? 'Stage must be 100 characters or fewer.'
        : '',
    value:
      values.value === ''
        ? 'Value is required.'
        : !isValueValid
          ? 'Value must be a non-negative number.'
          : '',
  };

  const isFormValid = !errors.companyId && !errors.name && !errors.stage && !errors.value;

  useEffect(() => {
    if (!open) {
      return;
    }

    setValues({
      ...emptyValues,
      ...initialValues,
      companyId: initialValues?.companyId || '',
      contactId: initialValues?.contactId ?? null,
      stage: initialValues?.stage || 'lead',
      value:
        initialValues?.value === null || initialValues?.value === undefined
          ? ''
          : String(initialValues.value),
      expectedCloseDate: normalizeCloseDate(initialValues?.expectedCloseDate),
    });
    setTouched({ companyId: false, name: false, stage: false, value: false });
  }, [initialValues, open]);

  useEffect(() => {
    if (!values.contactId) {
      return;
    }

    const isSelectedContactAvailable = contactOptions.some(
      (contact) => contact.id === values.contactId,
    );

    if (!isSelectedContactAvailable) {
      setValues((current) => ({ ...current, contactId: null }));
    }
  }, [contactOptions, values.contactId]);

  const handleChange = (field) => (event) => {
    setValues((current) => ({ ...current, [field]: event.target.value }));
  };

  const handleBlur = (field) => () => {
    setTouched((current) => ({ ...current, [field]: true }));
  };

  const handleCompanyChange = (_, company) => {
    setValues((current) => ({
      ...current,
      companyId: company?.id || '',
      contactId: null,
    }));
  };

  const handleContactChange = (_, contact) => {
    setValues((current) => ({ ...current, contactId: contact?.id ?? null }));
  };

  const handleSubmit = async (event) => {
    event.preventDefault();
    setTouched({ companyId: true, name: true, stage: true, value: true });

    if (!isFormValid) {
      return;
    }

    const payload = {
      name: values.name.trim(),
      value: Number(values.value),
      stage: values.stage.trim(),
      contactId: values.contactId,
      expectedCloseDate: values.expectedCloseDate || null,
    };

    if (mode === 'create') {
      await onSubmit({
        ...payload,
        companyId: values.companyId,
      });
      return;
    }

    await onSubmit(payload);
  };

  return (
    <Dialog open={open} onClose={isPending ? undefined : onClose} fullWidth maxWidth="sm">
      <DialogTitle>{mode === 'create' ? 'Create deal' : 'Edit deal'}</DialogTitle>

      <DialogContent sx={{ p: 2.5 }}>
        <Stack component="form" spacing={2} onSubmit={handleSubmit} sx={{ mt: 1 }}>
          <TextField
            required
            autoFocus
            label="Deal name"
            value={values.name}
            onBlur={handleBlur('name')}
            onChange={handleChange('name')}
            error={touched.name && Boolean(errors.name)}
            helperText={touched.name ? errors.name : undefined}
          />

          <Stack direction={{ xs: 'column', sm: 'row' }} spacing={2}>
            <TextField
              required
              fullWidth
              label="Value"
              type="number"
              slotProps={{ htmlInput: { min: 0, step: '0.01' } }}
              value={values.value}
              onBlur={handleBlur('value')}
              onChange={handleChange('value')}
              error={touched.value && Boolean(errors.value)}
              helperText={touched.value ? errors.value : undefined}
            />

            <TextField
              required
              fullWidth
              label="Stage"
              value={values.stage}
              onBlur={handleBlur('stage')}
              onChange={handleChange('stage')}
              error={touched.stage && Boolean(errors.stage)}
              helperText={touched.stage ? errors.stage : undefined}
              select
            >
              {stageOptions.map((stage) => (
                <MenuItem key={stage} value={stage}>
                  {stage}
                </MenuItem>
              ))}
            </TextField>
          </Stack>

          <Autocomplete
            fullWidth
            options={companyOptions}
            value={selectedCompany}
            loading={companiesQuery.isLoading}
            onBlur={handleBlur('companyId')}
            onChange={handleCompanyChange}
            disabled={mode === 'edit'}
            isOptionEqualToValue={(option, value) => option.id === value.id}
            getOptionLabel={(option) => option?.name || ''}
            noOptionsText={companiesQuery.isLoading ? 'Loading companies...' : 'No companies found'}
            renderInput={(params) => (
              <TextField
                {...params}
                required
                label="Company"
                error={touched.companyId && Boolean(errors.companyId)}
                helperText={
                  touched.companyId
                    ? errors.companyId
                    : companiesQuery.isError
                      ? 'Failed to load companies.'
                      : mode === 'edit'
                        ? 'Company is immutable once a deal is created.'
                        : undefined
                }
                InputProps={{
                  ...params.InputProps,
                  endAdornment: (
                    <>
                      {companiesQuery.isLoading ? (
                        <CircularProgress color="inherit" size={20} />
                      ) : null}
                      {params.InputProps.endAdornment}
                    </>
                  ),
                }}
              />
            )}
          />

          <Autocomplete
            fullWidth
            options={contactOptions}
            value={selectedContact}
            loading={contactsQuery.isLoading && Boolean(values.companyId)}

            loading={contactsQuery.isLoading && Boolean(values.companyId)}
            disabled={!values.companyId}
            onChange={handleContactChange}
            isOptionEqualToValue={(option, value) => option.id === value.id}
            getOptionLabel={(option) => option?.name || ''}
            noOptionsText={
              !values.companyId
                ? 'Select a company first'
                : contactsQuery.isLoading
                  ? 'Loading contacts...'
                  : 'No contacts found'
            }
            renderInput={(params) => (
              <TextField
                {...params}
                label="Contact (optional)"
                helperText={
                  contactsQuery.isError && values.companyId
                    ? 'Failed to load contacts.'
                    : undefined
                }
                InputProps={{
                  ...params.InputProps,
                  endAdornment: (
                    <>
                      {contactsQuery.isLoading && values.companyId ? (
                        <CircularProgress color="inherit" size={20} />
                      ) : null}
                      {params.InputProps.endAdornment}
                    </>
                  ),
                }}
              />
            )}
          />

          <TextField
            fullWidth
            label="Expected close date"
            type="date"
            InputLabelProps={{ shrink: true }}
            value={values.expectedCloseDate}
            onChange={handleChange('expectedCloseDate')}
          />

          <button type="submit" hidden />
        </Stack>
      </DialogContent>

      <DialogActions className="crm-dialog-actions">
        <Button onClick={onClose} disabled={isPending}>
          Cancel
        </Button>
        <Button variant="contained" onClick={handleSubmit} disabled={isPending}>
          {mode === 'create' ? 'Create' : 'Save'}
        </Button>
      </DialogActions>
    </Dialog>
  );
}

import {
  Button,
  Chip,
  Paper,
  Stack,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Typography,
} from '@mui/material';
import EditOutlined from '@ant-design/icons/EditOutlined';
import EyeOutlined from '@ant-design/icons/EyeOutlined';
import formatDate from 'utils/formatDate';

const stageColors = {
  lead: 'default',
  qualified: 'info',
  proposal: 'warning',
  negotiation: 'secondary',
  'closed-won': 'success',
  'closed-lost': 'error',
};

function formatCurrency(value) {
  if (value === null || value === undefined || Number.isNaN(Number(value))) {
    return '—';
  }

  return new Intl.NumberFormat('en-US', {
    style: 'currency',
    currency: 'USD',
    maximumFractionDigits: 0,
  }).format(Number(value));
}

function ActionCell({ deal, onView, onEdit }) {
  return (
    <TableCell align="right">
      <Stack direction="row" spacing={1} justifyContent="flex-end">
        <Button size="small" startIcon={<EyeOutlined />} onClick={() => onView(deal)}>
          View
        </Button>
        <Button size="small" startIcon={<EditOutlined />} onClick={() => onEdit(deal)}>
          Edit
        </Button>
      </Stack>
    </TableCell>
  );
}

