              <TableCell>{companiesById[deal.companyId] || deal.companyId}</TableCell>
              <TableCell>{deal.contactId || '—'}</TableCell>
              <TableCell>{formatCurrency(deal.value)}</TableCell>
              <TableCell>{formatDate(deal.expectedCloseDate)}</TableCell>
