import { Injectable } from '@nestjs/common';
import { DataSource } from 'typeorm';
import { BaseRepository } from '../../core/database/base.repository';
import { DealEntity } from './deal.entity';
import { DealListQueryDto } from './dto';

@Injectable()
export class DealRepository extends BaseRepository<DealEntity> {
  constructor(dataSource: DataSource) {
    super(DealEntity, dataSource.createEntityManager());
  }

  async findWithFilter(query: DealListQueryDto) {
    const page = query.page ?? 1;
    const pageSize = query.pageSize ?? 10;

    const queryBuilder = this.createQueryBuilder('deal');

    if (query.stage) {
      queryBuilder.andWhere('deal.stage = :stage', { stage: query.stage });
    }

    if (query.companyId) {
      queryBuilder.andWhere('deal.companyId = :companyId', {
        companyId: query.companyId,
      });
    }

    const [items, total] = await queryBuilder
      .orderBy('deal.createdAt', 'DESC')
      .skip((page - 1) * pageSize)
      .take(pageSize)
      .getManyAndCount();

    return {
      items,
      total,
      page,
      pageSize,
      totalPages: total === 0 ? 0 : Math.ceil(total / pageSize),
    };
  }
}
import {
  Entity,
  PrimaryGeneratedColumn,
  Column,
  CreateDateColumn,
  UpdateDateColumn,
  DeleteDateColumn,
} from 'typeorm';

@Entity('deals')
export class DealEntity {
  @PrimaryGeneratedColumn('uuid')
  id: string;

  @Column({ type: 'varchar', length: 255, comment: 'Deal name' })
  name: string;

  @Column({ type: 'double precision', comment: 'Deal value' })
  value: number;

  @Column({ type: 'varchar', length: 100, default: 'lead', comment: 'Deal stage' })
  stage: string;

  @Column({ type: 'uuid', comment: 'Related company id' })
  companyId: string;

  @Column({ type: 'uuid', nullable: true, comment: 'Related contact id' })
  contactId: string | null;

  @Column({ type: 'date', nullable: true, comment: 'Expected close date' })
  expectedCloseDate: string | null;

  @CreateDateColumn({ type: 'timestamptz', comment: 'Creation timestamp' })
  createdAt: Date;

  @UpdateDateColumn({ type: 'timestamptz', comment: 'Update timestamp' })
  updatedAt: Date;

  @DeleteDateColumn({
    type: 'timestamptz',
    nullable: true,
    select: false,
    comment: 'Soft delete timestamp',
  })
  deletedAt: Date;
}
